mapper.update:
UPDATE homework_question_answer
SET score = #{score}, annotation = #{annotation}
WHERE homework_id = #{homeworkId} AND question_id = #{questionId}
  AND question_type = #{questionType} AND student_id = #{studentId}

mapper.select:
SELECT * FROM homework_question_answer
WHERE homework_id = #{homeworkId} AND question_id = #{questionId}
  AND question_type = #{questionType} AND student_id = #{studentId}
